# -*- coding: utf-8 -*-
# 第 76-100 课内容数据
LESSONS_PART = [

# ============ 第6章 游戏对象与组件交互 (76-90) ============
{"num":76,"title":"实例化 Instantiate 动态创建对象","summary":"掌握 Instantiate 创建对象：生成子弹、敌人、金币，理解克隆与预制体。","keywords":"instantiate,实例化,克隆,动态创建,生成","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解实例化的作用","掌握 Instantiate 语法","用实例化生成游戏对象"],
 "intro":"游戏里到处是“动态生成”：按一下射一颗子弹、刷一波敌人。这全靠实例化（Instantiate）。",
 "sections":[
  {"h":"什么是实例化","lead":"“从模板复制出新对象”。",
   "steps":["实例化 = 根据一个“模板”（预制体或已有对象）在运行时创建新对象。","语法：Object.Instantiate(模板) 或简写 Instantiate(模板)。","最常用模板是预制体（第 32-34 课），也可是场景里的现有对象。","例：Instantiate(bulletPrefab); 生成一个子弹对象。","【返回引用】GameObject newObj = Instantiate(prefab); 可拿到新对象做后续操作。","【指定位置】Instantiate(prefab, position, rotation); 在指定位置与角度生成。","Unity 的简写：MonoBehaviour 里的 Instantiate 可直接使用（省略 Object）。"],
   "tips":[{"t":"note","c":"学会实例化 = 学会“量产”：一颗子弹的预制体可以瞬间变出 100 颗。"}]},
  {"h":"实例化实战：发射子弹","lead":"做一个按空格发射子弹的效果。",
   "steps":["先做【子弹预制体】：场景里创建一个 Sphere（小球），缩小到 (0.2,0.2,0.2)，加黄色材质，加 Rigidbody。","把它拖到 Project 的 Prefabs 文件夹变成预制体，然后从场景中删除这个“模板原型”。","把子弹预制体拖回场景放在原点外，选中它，改名为 Bullet，确认有 Rigidbody 后把它也变成预制体（或在 Prefabs 里直接用它）。","创建脚本 Shooter，挂到空对象上：","public GameObject bulletPrefab; // 在 Inspector 拖入子弹预制体","void Update() { if (Input.GetKeyDown(KeyCode.Space)) { Instantiate(bulletPrefab, transform.position, Quaternion.identity); } }","保存播放：按空格，场景里不断生成子弹！","【说明】Quaternion.identity 表示“无旋转”（Quaternion 四元数第 81 课提及）。","【进阶】给子弹脚本让它自己向前飞：在子弹预制体上加 MoveForward 脚本（transform.Translate(Vector3.forward * speed * Time.deltaTime)）。"],
   "tips":[{"t":"success","c":"Instantiate + 预制体 = 游戏开发的核心循环：生成→行动→销毁。"}]},
 ],
 "errors":[{"err":"实例化出的对象没有任何位置/属性？","why":"忘了设置 position/rotation 参数","fix":"用 Instantiate(prefab, pos, rot) 三个参数版本。"},{"err":"每帧生成一堆对象导致卡顿？","why":"在 Update 里无条件实例化","fix":"只在触发时生成（按键/定时），并记得销毁（第 77 课）。"}],
 "exercise":["把子弹做成预制体并通过 Instantiate 生成","给生成的子弹加一个自动前进的脚本","把生成位置改成枪口处的一个空对象"],
 "summary":"实例化已掌握。下一课学习销毁对象 Destroy。"},

{"num":77,"title":"销毁对象 Destroy","summary":"掌握 Destroy 删除对象、延迟销毁、资源清理，与实例化配合控制对象生命周期。","keywords":"destroy,销毁,删除对象,延迟销毁,生命周期","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握 Destroy 语法","掌握延迟销毁","理解销毁时机"],
 "intro":"生成了对象不销毁，内存和画面会被占满。Destroy 就是“清理工”。",
 "sections":[
  {"h":"Destroy 基础","lead":"立即/延时删除。",
   "steps":["【立即销毁】Destroy(gameObject); 删除当前脚本挂载的对象。","【销毁指定对象】Destroy(targetObject); 删除任意对象引用。","【延迟销毁】Destroy(gameObject, 2f); 2 秒后销毁（第二参数是秒数）。","【销毁组件】Destroy(GetComponent<Rigidbody>()); 也可以销毁组件。","Destroy 在当前帧结束时真正删除，避免物理中途出错。","【注意】销毁后不能再访问该对象，否则报“Missing”错误。","【清理】配合实例化：生成的子弹飞出去后要销毁，避免无限堆积。","【在碰撞时销毁】OnCollisionEnter 里 Destroy(gameObject)（第 92-96 课）。"],
   "tips":[{"t":"warn","c":"访问已销毁对象 = 经典报错（MissingReferenceException）。操作前先判空 if (obj != null)。"}]},
  {"h":"实战：子弹自动销毁","lead":"让子弹 3 秒后消失。",
   "steps":["在子弹预制体上加脚本 BulletAutoDestroy：","void Start() { Destroy(gameObject, 3f); }","这样子弹生成 3 秒后自动消失，不占资源。","保存、播放，按空格发射子弹，观察 3 秒后子弹消失。","【更真实】在子弹碰到墙壁时立即销毁：加 OnCollisionEnter 方法（第 96 课触发/碰撞事件），碰撞时 Destroy(gameObject)。","【销毁后处理】如需在销毁前做特效/加分，可在 Destroy 前先执行逻辑，或写 OnDestroy 方法（第 71 课）。","【注意】Destroy 是“下一帧删”，若需立即处理可用 DestroyImmediate（编辑器用，运行时少用）。"],
   "tips":[{"t":"success","c":"对象生命周期闭环：Instantiate 出生 → 行动 → Destroy 死亡。把控好它，项目不乱。"}]},
 ],
 "errors":[{"err":"报错：MissingReferenceException?","why":"访问了已销毁的对象","fix":"用 if (obj != null) 判空，或在销毁后避免再次访问。"}],
 "exercise":["让生成的子弹 2 秒后自动销毁","在子弹碰撞时销毁它","说出 Destroy 延迟销毁的用法"],
 "summary":"Destroy 已掌握。下一课学标签与层级，给对象“打标签”。"},

{"num":78,"title":"标签 Tag 与层级 Layer","summary":"掌握 Tag（标签）与 Layer（层级）的设置与用途，按类别区分对象。","keywords":"tag,标签,layer,层级,comparetag,碰撞矩阵","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 Tag 与 Layer 的区别","掌握设置与判断","了解 Layer 在碰撞中的作用"],
 "intro":"“它是敌人还是子弹？”——用 Tag 给对象打标签，用 Layer 做分类管理。两者看似像，用途不同。",
 "sections":[
  {"h":"标签 Tag","lead":"给对象“贴名牌”。",
   "steps":["选中对象，Inspector 顶部有【Tag】下拉框（默认 Untagged）。","【使用内置标签】下拉选择 MainCamera、Player、Enemy 等（新项目含默认标签）。","【新建标签】点下拉框底部的【Add Tag…】→ 在 Tags 列表输入新标签名（如 Enemy）→ 保存。","新建后回到对象 Tag 下拉选择刚建的 Enemy。","【代码判断】gameObject.CompareTag(\"Enemy\") 返回 bool（推荐，比 == 高效且防报错）。","【用途】区分“这是什么”：敌人、玩家、墙壁、道具。","【删除标签】Tags 列表选中标签点减号（使用中的标签不能删）。"],
   "tips":[{"t":"note","c":"判断标签优先用 CompareTag 而不是 gameObject.tag == \"...\"，后者拼错会报错。"}]},
  {"h":"层级 Layer","lead":"给对象“分类编组”。",
   "steps":["选中对象，Inspector 顶部的【Layer】下拉框（默认 Default）。","【新建 Layer】点下拉框 →【Add Layer…】→ 在空白槽输入层名（如 Player、Enemy、Wall）。","选中对象 Layer 设为对应层。","【用途1 碰撞矩阵】：Edit→Project Settings→Physics→Layer Collision Matrix，控制“哪些层之间会发生碰撞”（第 99 课）。","【用途2 相机渲染】：Camera 的 Culling Mask 可只渲染指定层。","【用途3 射线过滤】：Raycast 指定只检测某些层（第 100 课）。","【代码获取层编号】gameObject.layer（int）与 LayerMask.NameToLayer(\"Player\") 配合。","【区别】Tag=标识身份（用于逻辑判断）；Layer=分类编组（用于物理/渲染控制）。"],
   "tips":[{"t":"note","c":"一个对象只能有一个 Tag 和一个 Layer；Layer 编号 0-31。"}]},
 ],
 "errors":[{"err":"CompareTag 报错：不存在该标签？","why":"标签名拼错或未创建","fix":"确认 Tag 已在 Tag Manager 里创建，且代码里拼写一致。"}],
 "exercise":["创建一个 Enemy 标签并打到一个对象上","在代码中用 CompareTag 判断并打印","新建一个 Enemy Layer 并设置到对象"],
 "summary":"Tag 与 Layer 已掌握。下一课学习查找对象的方法。"},

{"num":79,"title":"查找对象与组件 Find 系列","summary":"掌握 Find、FindWithTag、FindObjectOfType 等查找方法，按需获取对象引用。","keywords":"find,findobjectoftype,findwithtag,查找对象,getcomponent","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握常用查找方法","理解查找的性能成本","学会缓存查找结果"],
 "intro":"脚本怎么“找到”场景里的其他对象？本课讲透 Find 系列方法，并教你优雅地管理引用。",
 "sections":[
  {"h":"按名称与标签查找","lead":"最快的方式。",
   "steps":["【按名称】GameObject.Find(\"Enemy\"); 返回名为 Enemy 的对象（只能找激活的对象）。","【按标签】GameObject.FindWithTag(\"Enemy\"); 返回第一个该标签的对象；FindGameObjectsWithTag 返回数组（全部）。","【推荐】FindWithTag 比 Find 快，且不受改名影响，优先用标签。","【限制】Find 系列性能较慢，且只能在激活对象里找。","【使用注意】不要在 Update 里每帧调用 Find，应在 Start/Awake 里查找并缓存。","【单例替代】项目中常用“单例/静态引用”来避免 Find（第 86 课）。"],
   "tips":[{"t":"warn","c":"每帧 Find 是性能杀手。一次查找、存进字段、反复使用，这是黄金法则。"}]},
  {"h":"按类型查找与组件查找","lead":"更通用。",
   "steps":["【查找第一个组件类型】FindObjectOfType<Player>() 返回场景中第一个 Player 脚本（MonoBehaviour 已弃用单数版本，新版本用 FindFirstObjectByType）。","【查找全部】FindObjectsOfType<Enemy>() 返回数组（新版 FindObjectsByType）。","【获取自身组件】GetComponent<Rigidbody>()（第 80 课详讲）。","【子对象组件】GetComponentInChildren<T>() 在子对象中找；GetComponentInParent<T>() 在父对象中找。","【实战】在 GameManager 的 Start 里：Player player = FindObjectOfType<Player>(); 拿到玩家引用。","【注意】新版 Unity 推荐 FindFirstObjectByType / FindObjectsByType（加 FindObjectsSortMode 参数）。","这些查找按类型扫描，相对较慢，同样要缓存。"],
   "tips":[{"t":"note","c":"能不 Find 就不 Find：优先用 public 字段在 Inspector 拖引用（第 84 课序列化）。"}]},
 ],
 "errors":[{"err":"Find 返回 null？","why":"对象未激活、名字不对或标签错误","fix":"确认对象存在且激活；检查名字/标签拼写；用 Debug.Log 验证。"}],
 "exercise":["用 FindWithTag 查找一个敌人对象","用 FindObjectOfType 获取玩家脚本引用","把查找结果缓存到字段并在 Update 中复用"],
 "summary":"查找方法已掌握。下一课学组件访问 GetComponent。"},

{"num":80,"title":"组件访问 GetComponent","summary":"掌握 GetComponent 获取组件、在脚本间通信、注意判空。","keywords":"getcomponent,组件访问,获取组件,组件通信,判空","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握 GetComponent 语法","掌握跨脚本访问","养成判空习惯"],
 "intro":"脚本要操控“别的组件”（刚体、其他脚本、Renderer），全靠 GetComponent。这是最常用的 API 之一。",
 "sections":[
  {"h":"GetComponent 基础","lead":"从对象身上“取组件”。",
   "steps":["语法：组件类型 变量 = GetComponent<组件类型>();","例：Rigidbody rb = GetComponent<Rigidbody>(); 拿到这个对象上的刚体组件。","之后就能用 rb.AddForce(...) 等操作。","【获取其他脚本】Player player = GetComponent<Player>(); 访问另一个挂在同一对象上的脚本。","【获取子/父对象的组件】GetComponentInChildren<T>() / GetComponentInParent<T>()。","【注意】对象上没有该组件时返回 null，操作会报错。","【判空】if (rb != null) { rb.AddForce(...); } 安全写法。","【性能】GetComponent 较快但仍建议缓存到字段（Awake 里获取）。"],
   "tips":[{"t":"success","c":"铁律：GetComponent 放 Awake 里缓存到字段，Update 里直接用缓存，永不每帧 GetComponent。"}]},
  {"h":"实战：脚本间通信","lead":"让两个脚本协作。",
   "steps":["创建脚本 Health：定义 public int hp = 100; public void TakeDamage(int dmg) { hp -= dmg; Debug.Log(\"剩余HP：\" + hp); }","再创建脚本 Attacker，挂到另一个对象上，在 Update 里检测按键：","if (Input.GetKeyDown(KeyCode.Space)) { Health h = GetComponent<Health>(); if (h != null) { h.TakeDamage(10); } }","把 Health 和 Attacker 挂到同一个对象上，播放按空格：血量每次减 10。","若 Health 挂在不同对象，用 public Health target; 在 Inspector 拖入，或用 FindObjectOfType（第 79 课）。","【核心】组件通信 = GetComponent 拿到对方脚本 → 调用它的 public 方法/字段。","【高级】用事件/接口解耦（第 68/83 课），让代码更健壮。"],
   "tips":[{"t":"note","c":"跨脚本通信是游戏开发核心能力：血量脚本、攻击脚本、UI 脚本互相配合全靠它。"}]},
 ],
 "errors":[{"err":"GetComponent 返回 null 调用报错？","why":"对象上确实没有该组件","fix":"先判空 if (comp != null)；或确认组件已添加到对象上。"}],
 "exercise":["用 GetComponent 拿到刚体并打印其质量","创建 Health 与 Attacker 两个脚本实现互相调用","用 GetComponentInChildren 访问子对象上的组件"],
 "summary":"GetComponent 已掌握。下一课学 Transform 常用 API。"},

{"num":81,"title":"Transform 常用 API","summary":"掌握 transform 的移动、旋转、朝向、父子等高频 API，操控对象空间变换。","keywords":"transform,translate,rotate,lookat,forward,position","time":"约 16 分钟","difficulty":"入门",
 "objectives":["掌握移动类 API","掌握旋转与朝向","掌握坐标转换"],
 "intro":"transform 是每个对象都有的组件，操控它的位置/旋转是写游戏逻辑的第一步。本课汇总最常用的 API。",
 "sections":[
  {"h":"移动与位置","lead":"让对象“动起来”。",
   "steps":["【直接改位置】transform.position = new Vector3(1, 2, 3);（世界坐标瞬移）。","【相对自身移动】transform.Translate(Vector3.forward * speed * Time.deltaTime); 沿自身前方移动，配合旋转可实现“朝哪走哪”。","【Translate 方向参数】transform.Translate(dir, Space.Self)（自身空间，默认）或 Space.World（世界空间）。","【取位置】transform.position（世界）、transform.localPosition（局部）。","【取朝向】transform.forward（前方单位向量）、transform.right、transform.up。","【插值移动】transform.position = Vector3.MoveTowards(current, target, speed * Time.deltaTime); 匀速靠近目标，好用。","【平滑移动】Vector3.Lerp（线性插值）：transform.position = Vector3.Lerp(a, b, t); t 是 0-1 的比例。"],
   "tips":[{"t":"note","c":"MoveTowards 匀速、Lerp 渐进，是两个高频移动方案，务必掌握。"}]},
  {"h":"旋转与朝向","lead":"让对象“转起来”。",
   "steps":["【直接设旋转】transform.rotation = Quaternion.Euler(0, 90, 0); 用欧拉角转 90 度（Quaternion 四元数，避免直接设角度）。","【旋转增量】transform.Rotate(0, 90, 0); 绕 Y 轴转 90 度；transform.Rotate(Vector3.up, 90f); 等价。","【旋转速度】transform.Rotate(Vector3.up * rotateSpeed * Time.deltaTime); 持续旋转。","【看向目标】transform.LookAt(target); 让对象正面朝向目标位置（自动旋转 Z 轴对齐）。","【获取角度】transform.eulerAngles 返回 (x,y,z) 角度。","【朝向目标方向移动】dir = (target - transform.position).normalized; transform.Translate(dir * speed * Time.deltaTime, Space.World);","【Quaternion 要点】rotation 是四元数，不能直接改 x/y/z，用 eulerAngles 或 Rotate。","【平滑旋转】Quaternion.Slerp（球面插值）：transform.rotation = Quaternion.Slerp(a, b, t);"],
   "tips":[{"t":"danger","c":"永远不要直接改 transform.rotation.x/y/z！用 Quaternion.Euler 或 Rotate。四元数第 2 课会深讲。"}]},
  {"h":"父子操作","lead":"管理层级。",
   "steps":["【取父对象】transform.parent 或 transform.root（最顶层）。","【设父对象】transform.SetParent(newParent, true); 第二个参数 true=保持世界坐标。","【子对象数量】transform.childCount。","【取第几个子对象】transform.GetChild(0)。","【遍历子对象】foreach (Transform child in transform) { ... }。","【查找子对象】transform.Find(\"名字\") 按名字找子对象（比 Find 快）。","【销毁所有子对象】在子对象列表里逐个 Destroy。","【本地与世界坐标转换】transform.InverseTransformDirection(dir) 把世界方向转成自身方向；TransformPoint 等。","【实用组合】把武器挂到手上：weapon.SetParent(hand, false);"],
   "tips":[{"t":"success","c":"Transform API 是 3D 编程的基本功：translate 移动、rotate 旋转、lookAt 朝向、setParent 挂载。"}]},
 ],
 "errors":[{"err":"旋转数值莫名“跳变”？","why":"直接改了 Quaternion 的 x/y/z","fix":"使用 Quaternion.Euler 赋值或用 eulerAngles。"}],
 "exercise":["用 Translate 让物体沿自身前方移动并旋转","用 LookAt 让物体始终看向目标","用 SetParent 把子弹挂到枪口上"],
 "summary":"Transform API 已掌握。下一课学协程 Coroutine。"},

{"num":82,"title":"协程 Coroutine","summary":"掌握协程：实现延时、分帧执行，用 IEnumerator 与 yield 写异步流程。","keywords":"协程,coroutine,ienumerator,yield,延时,startcoroutine","time":"约 16 分钟","difficulty":"入门",
 "objectives":["理解协程的原理","掌握 StartCoroutine 与 yield","实现延时与分帧逻辑"],
 "intro":"“等 2 秒再执行”“一帧一帧推进”这类“异步”需求，用协程最优雅。它是 Unity 独有的一套写法。",
 "sections":[
  {"h":"什么是协程","lead":"“可以暂停”的函数。",
   "steps":["协程（Coroutine）是一个可以“暂停（yield）再继续”的方法，适合写需要等待的流程。","【为什么需要】Update 每帧都执行，没法“等 2 秒再干某事”。协程可以暂停指定时间。","【语法】返回类型必须是 IEnumerator：IEnumerator MyCoroutine() { ... }","【启动】StartCoroutine(MyCoroutine()); 或 StartCoroutine(\"MyCoroutine\")。","【暂停】yield return null; // 暂停一帧","【延时】yield return new WaitForSeconds(2f); // 暂停 2 秒","【停止】StopCoroutine(名/引用)；StopAllCoroutines()。","【注意】协程挂在该脚本所在对象上；对象销毁则协程停止。","【常用 yield】WaitForSeconds、WaitForEndOfFrame、WaitUntil(条件)、WaitForSecondsRealtime（不受时间缩放影响）。"],
   "tips":[{"t":"note","c":"协程不是多线程！它仍在主线程，只是“分时执行”，不阻塞其他代码。"}]},
  {"h":"协程实战：延时与循环生成","lead":"写两个经典用法。",
   "steps":["【延时打印】新建脚本 CoroutineDemo：","IEnumerator DelayLog() { Debug.Log(\"开始\"); yield return new WaitForSeconds(2f); Debug.Log(\"2秒后\"); }","void Start() { StartCoroutine(DelayLog()); }","播放：2 秒后才打印“2秒后”，不阻塞其他。","【循环生成】每 1 秒生成一个球，共 5 个：","IEnumerator SpawnLoop() { for (int i = 0; i < 5; i++) { Instantiate(bulletPrefab, transform.position, Quaternion.identity); yield return new WaitForSeconds(1f); } }","【等待条件】yield return new WaitUntil(() => hp <= 0); 等血量归零再继续。","【分帧加载】大循环里每几帧 yield 一次，避免卡顿（配合第 16 章优化）。","【停止】在 Update 里按某个键 StopCoroutine。","体会协程让“流程控制”像写剧本一样顺畅。"],
   "tips":[{"t":"success","c":"协程三大件：IEnumerator 返回类型、yield return 暂停、StartCoroutine 启动。"}]},
 ],
 "errors":[{"err":"报错：yield 只能在 IEnumerator 方法里使用？","why":"方法返回类型不是 IEnumerator","fix":"把方法返回类型改成 IEnumerator，并确保有 yield return。"}],
 "exercise":["写一个 3 秒倒计时协程","用协程每 0.5 秒生成一个方块","写一个等待血量归零的协程"],
 "summary":"协程已掌握。下一课学事件与委托 delegate。"},

{"num":83,"title":"事件与委托 delegate","summary":"掌握委托与事件：把方法当作参数传递，实现“发布-订阅”的解耦通信。","keywords":"委托,delegate,事件,event,发布订阅,回调","time":"约 16 分钟","difficulty":"入门",
 "objectives":["理解委托的概念","掌握声明与使用","理解事件与观察者模式"],
 "intro":"“角色死亡时，UI 要刷新、音效要播放、任务要更新”——用事件把“谁死了”广播出去，让关心它的人各自响应。",
 "sections":[
  {"h":"委托 delegate","lead":"“方法的类型”。",
   "steps":["委托 = 一种“方法的类型”，可以声明一个“存放方法”的变量。","【声明】public delegate void MyDelegate(); 声明一个“无参无返回值”的方法类型。","【定义事件】public event MyDelegate OnDeath; 声明一个事件（只能 += / -= 挂接方法）。","【订阅】OnDeath += DieHandler; 把方法挂到事件上（在 Start 或 Awake 里）。","【退订】OnDeath -= DieHandler;（在 OnDisable 里退订防泄漏）。","【触发】OnDeath?.Invoke(); 触发所有订阅的方法（?. 判空防报错）。","【带参委托】delegate void DamageEvent(int amount); 事件可以携带数据。","【系统预置】UnityEngine.Events.UnityEvent 可用于 Inspector 可视配置（第 167 课 UI 按钮）。"],
   "tips":[{"t":"note","c":"“事件是广播站”：只负责喊“我死了”，不关心谁在听。让代码解耦、扩展容易。"}]},
  {"h":"实战：死亡事件驱动","lead":"做一个事件系统。",
   "steps":["创建脚本 HealthEvent：","public event System.Action OnDeath; // 直接用系统 Action 委托","public int hp = 100;","public void TakeDamage(int dmg) { hp -= dmg; if (hp <= 0) { OnDeath?.Invoke(); } }","创建脚本 DeathListener（挂到另一对象）：","public HealthEvent health;","void Start() { health = FindObjectOfType<HealthEvent>(); health.OnDeath += HandleDeath; }","void HandleDeath() { Debug.Log(\"角色死亡！刷新 UI、播放音效、任务更新\"); }","void OnDisable() { if (health != null) health.OnDeath -= HandleDeath; }","播放：给角色扣血到 0，触发死亡事件，监听者响应。","【要点】订阅用 +=、退订用 -=、触发用 ?.Invoke()。","【好处】Health 不需要知道谁在听，新增响应者不用改 Health 代码。"],
   "tips":[{"t":"success","c":"事件/委托是游戏架构解耦的核心，配合第 86 课单例更好用。"}]},
 ],
 "errors":[{"err":"事件触发时报 null 引用？","why":"没人订阅时 Invoke 可能 null","fix":"用 OnDeath?.Invoke()（?. 判空）或先判断 OnDeath != null。"}],
 "exercise":["声明一个带 int 参数的事件","订阅、触发、退订完整走一遍","用 UnityEvent 在 Inspector 配置一个响应"],
 "summary":"委托与事件已掌握。下一课学序列化字段 SerializeField。"},

{"num":84,"title":"序列化字段 [SerializeField] 与 [Header]","summary":"掌握在 Inspector 中暴露/组织字段，让配置可视化、易调优。","keywords":"serializefield,序列化,header,range,inspector配置","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握 SerializeField","掌握 Header/Range 特性","理解序列化的意义"],
 "intro":"直接在 Inspector 里调数值、拖引用，比写死代码爽多了。这一切靠“序列化”。",
 "sections":[
  {"h":"public 字段与序列化","lead":"字段出现在 Inspector。",
   "steps":["【public 字段】自动出现在 Inspector 底部：public float speed = 5f; 可在面板改。","【好处】不用改代码就能调参（速度、血量、颜色）。","【private 字段】默认不在面板显示。","【序列化私有字段】[SerializeField] private float speed = 5f; 让私有字段也能在面板显示。","【不序列化】[System.NonSerialized] public int temp; 让 public 字段不出现在面板。","【序列化支持类型】int、float、string、bool、Vector3、GameObject 引用、组件引用、枚举、自定义类/List/数组。","【自动保存】面板改动保存到场景/预制体，下次打开还在。"],
   "tips":[{"t":"note","c":"能用 Inspector 配置的就不写死：调参不用进代码，这是敏捷开发的关键。"}]},
  {"h":"常用特性 Attribute","lead":"让面板更整齐、更好用。",
   "steps":["【Header】[Header(\"移动设置\")] 在字段上方加分组标题。","【Tooltip】[Tooltip(\"每秒移动距离\")] 鼠标悬停显示提示。","【Range】[Range(0, 10)] public float speed; 显示滑动条，限制范围。","【Space】[Space(10)] 添加垂直空隙。","【Min】[Min(0)] 限制最小值；[MinMaxSlider] 双端滑条（进阶）。","【组合示例】","[Header(\"移动\")] public float moveSpeed = 5f;","[Range(0f, 100f)] public float jumpPower = 20f;","[Tooltip(\"最大血量\")] public int maxHp = 100;","保存后在 Inspector 看分组、滑条、提示效果。","【实战】把前面课程里的数字全部提取成序列化字段，让它们可调。"],
   "tips":[{"t":"success","c":"优秀的脚本 = 逻辑代码 + 清晰的序列化配置面板，让策划/自己免改代码调参数。"}]},
 ],
 "errors":[{"err":"改了 Inspector 的值但运行时没变？","why":"可能被代码覆盖（Start 里重新赋值）","fix":"检查脚本是否有赋值覆盖；优先在字段默认值/面板里统一配置。"}],
 "exercise":["把速度等参数改成 [SerializeField] 字段","用 Header 分组、Range 限制范围","体验在 Inspector 调参无需改代码"],
 "summary":"序列化字段已掌握。下一课学 ScriptableObject 数据对象。"},

{"num":85,"title":"ScriptableObject 数据对象","summary":"掌握 ScriptableObject：创建独立的数据资产（物品、武器、配置），复用与热更新。","keywords":"scriptableobject,数据对象,资产,配置,createassetmenu","time":"约 16 分钟","difficulty":"入门",
 "objectives":["理解 ScriptableObject 概念","掌握创建数据资产","用资产存游戏配置"],
 "intro":"把“物品属性、武器数值、关卡配置”做成独立的数据资产文件，改数据不用改代码、还能批量复用。这就是 ScriptableObject。",
 "sections":[
  {"h":"ScriptableObject 是什么","lead":"“数据变成资产文件”。",
   "steps":["ScriptableObject 是一种“数据容器”，可以生成 .asset 资源文件存放在 Project 里。","与普通类区别：普通类数据存在场景/脚本里；SO 数据存在独立资产文件里，可被多个对象共享。","【典型用途】物品定义、武器参数、敌人配置、关卡数据、对话文本。","【好处1】可视化编辑数据（Inspector 里改数值即改资产）。","【好处2】一份数据多场景/多对象复用。","【好处3】方便策划配置、版本管理。","【注意】SO 存的是数据不是逻辑，适合“静态配置”；运行时改动不自动保存。"],
   "tips":[{"t":"note","c":"记忆：ScriptableObject = 数据版的预制体——预制体复用“对象+组件”，SO 复用“数据”。"}]},
  {"h":"创建并使用 SO 资产","lead":"一步步做“物品数据”。",
   "steps":["创建脚本 ItemData（继承 ScriptableObject）：","using UnityEngine;","[CreateAssetMenu(fileName = \"NewItem\", menuName = \"Game/Item Data\")]","public class ItemData : ScriptableObject { public string itemName; public string description; public int value; public Sprite icon; }","保存编译后，在 Project 右键 →【Create】→【Game/Item Data】，生成一个 .asset 文件。","选中它，在 Inspector 填写名字、描述、价值、图标。","再创建一个不同的 ItemData 资产（如“金币”“药水”），数据各自独立。","【引用使用】脚本里声明 public ItemData item; 在 Inspector 把资产拖入，读取 item.itemName。","【创建资产代码】ScriptableObject.CreateInstance<T>()（进阶）。","【注意事项】字段会被序列化，别放运行时状态（每帧变的值）。"],
   "tips":[{"t":"success","c":"物品、武器、敌人、关卡……把配置抽成 SO，是游戏数据架构的核心之一。"}]},
 ],
 "errors":[{"err":"Create 菜单里看不到自定义选项？","why":"脚本没加 CreateAssetMenu 特性或未编译","fix":"确认脚本继承 ScriptableObject 并带 [CreateAssetMenu(...)] 特性，保存后刷新。"}],
 "exercise":["创建一个武器数据 SO 资产","创建 3 种武器资产并填不同数值","在另一个脚本中引用并打印武器属性"],
 "summary":"ScriptableObject 已掌握。下一课学游戏架构核心：单例模式。"},

{"num":86,"title":"单例模式 Singleton","summary":"掌握单例：让某个管理器“全场景唯一且随时可访问”，搭建全局管理中枢。","keywords":"单例,singleton,instance,全局访问,管理器","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解单例的概念","掌握单例写法","用单例管理全局逻辑"],
 "intro":"“任何脚本都能拿到 GameManager”“得分管理只有一个实例”——单例模式解决这两个需求，是游戏开发最常用的模式。",
 "sections":[
  {"h":"什么是单例","lead":"“全游戏只此一个，且谁都能访问”。",
   "steps":["单例 = 一个类在整个游戏中只允许存在一个实例（Instance），并提供全局静态访问。","【为什么用】跨脚本通信频繁时，用单例代替 Find/拖引用，代码更简洁。","【典型】GameManager（游戏流程）、ScoreManager（分数）、AudioManager（音频）、UIManager（界面）。","【单例本质】一个 static 字段保存“唯一的自己”，通过 Instance 属性访问。","【注意】单例虽方便，滥用会耦合；架构上要克制（第 279 课设计模式）。"],
   "tips":[{"t":"note","c":"单例 = static 字段 + 赋值 + 全局访问，三行核心。"}]},
  {"h":"单例写法","lead":"标准模板。",
   "steps":["新建脚本 GameManager（继承 MonoBehaviour）：","public class GameManager : MonoBehaviour {","public static GameManager Instance;","void Awake() { if (Instance == null) { Instance = this; } else { Destroy(gameObject); } }","public int score;","public void AddScore(int n) { score += n; }","}","【说明】Awake 里把自己赋给 Instance；若已有实例则销毁重复的，保证唯一。","【跨场景保留】在 Awake 里加 DontDestroyOnLoad(gameObject); 让单例跨场景存活（第 238 课）。","【使用】任何脚本：GameManager.Instance.AddScore(10);","【进阶】泛型单例模板、属性封装（Instance 用属性 + get 自动查找）——进阶。","【实战】创建空对象挂 GameManager，在玩家脚本里调用 GameManager.Instance.AddScore(10)，打印分数。"],
   "tips":[{"t":"success","c":"单例让“谁都能找到总管”，但也别把所有逻辑塞进一个巨大单例，注意职责拆分。"}]},
 ],
 "errors":[{"err":"Instance 为 null？","why":"单例未挂载到场景或未初始化","fix":"确认对象上挂了单例脚本；在 Awake/Start 之后使用；跨场景需 DontDestroyOnLoad。"}],
 "exercise":["实现一个 ScoreManager 单例","在两个不同脚本里访问同一个单例","用 DontDestroyOnLoad 让单例跨场景保留"],
 "summary":"单例模式已掌握。下一课复习命名与代码规范，写“干净”的代码。"},

{"num":87,"title":"命名与代码规范实战","summary":"把规范落到代码上：可读性、注释、职责单一，写出专业级脚本。","keywords":"代码规范,命名,注释,可读性,重构,单一职责","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握命名与注释规范","理解职责单一原则","写出可维护的代码"],
 "intro":"代码是写给“未来的自己”看的。本课把规范真正用起来，让你的脚本专业、易维护。",
 "sections":[
  {"h":"命名规范落地","lead":"一眼看懂每个名字。",
   "steps":["【类/方法】大驼峰：PlayerController、StartMove、TakeDamage。","【字段/变量】小驼峰：playerSpeed、maxHp、isDead。","【常量】全大写：MAX_HP、GRAVITY。","【私有字段前缀】_ 开头（如 _hp）区分公有：private int _hp;（社区常用下划线风格）。","【布尔变量】is/ has/ can 前缀表状态：isDead、hasKey、canJump。","【禁止】不缩写到看不懂（btn 可，bt 不行）；不用拼音；不同语言混用。","【Unity 字段】public 的序列化字段名清晰表达用途：moveSpeed、damagePerHit。"],
   "tips":[{"t":"note","c":"好名字胜过注释：moveSpeed 比 spd 或“速度”更好。"}]},
  {"h":"注释与职责单一","lead":"让代码“自解释”+“小而专”。",
   "steps":["【注释规范】说明“为什么”而非“是什么”：// 用 Lerp 平滑跟随，避免瞬移","【块注释】类顶部写类的作用：/// <summary> 控制玩家移动 </summary>","【职责单一】一个脚本只做一件事：PlayerMove 管移动、PlayerHealth 管血量、PlayerAttack 管攻击，别大杂烩。","【方法小而精】一个方法只做一件事；过长拆分成子方法。","【去魔法数字】用常量/字段代替写死的数字：const int MAX_HP = 100。","【及时重构】代码重复出现两次以上就提取成方法/类。","【删除无用代码】注释掉的死代码直接删，Git 会记住历史。","【规范收尾】写完跑一遍确认无警告；把调试 Log 清理或保留有用的。"],
   "tips":[{"t":"success","c":"专业标准：脚本“小而专”、命名“自解释”、注释“说原因”、重复“必提取”。"}]},
 ],
 "errors":[{"err":"代码能跑但以后看不懂？","why":"缺规范与注释","fix":"从下一课起，所有新脚本都按本课规范书写，逐步养成习惯。"}],
 "exercise":["把之前写的脚本按本课规范重命名与整理","给类和方法补充 XML 注释","把一个大方法拆成两个职责单一的方法"],
 "summary":"代码规范已落地。下一课学 MonoBehaviour 消息 OnEnable/OnDisable 的妙用。"},

{"num":88,"title":"MonoBehaviour 消息 OnEnable/OnDisable","summary":"掌握启用/禁用相关的生命周期消息，用于订阅退订、显隐逻辑。","keywords":"onenable,ondisable,启用,禁用,生命周期,订阅","time":"约 12 分钟","difficulty":"入门",
 "objectives":["理解 OnEnable/OnDisable 时机","掌握事件订阅退订最佳实践","掌握对象显隐控制"],
 "intro":"上节课提到事件要在 OnDisable 里退订。本课系统讲 OnEnable/OnDisable 这对“开关门”方法。",
 "sections":[
  {"h":"OnEnable / OnDisable","lead":"对象“激活/失活”时触发。",
   "steps":["【OnEnable】对象被启用（激活）时调用：首次加载时、从失活恢复时、脚本组件勾选启用时。","【OnDisable】对象被禁用时调用：失活、脚本禁用、销毁前。","【时机细节】首次激活时顺序：Awake → OnEnable → Start。","【与 SetActive】gameObject.SetActive(false) 失活会触发 OnDisable；再 SetActive(true) 触发 OnEnable。","【用途1】启用时初始化、禁用时清理：OnEnable 里开启协程、OnDisable 里停止。","【用途2】事件订阅退订的最佳位置（第 83 课）：OnEnable 订阅 +=、OnDisable 退订 -=。","【注意】组件禁用（勾选取消）也触发 OnDisable；对象销毁会先 OnDisable 再 OnDestroy。"],
   "tips":[{"t":"note","c":"铁律：事件订阅在 OnEnable、退订在 OnDisable，避免“幽灵订阅”导致报错/泄漏。"}]},
  {"h":"实战：显隐与订阅","lead":"做一个可开关的对象。",
   "steps":["新建脚本 ToggleDemo，挂到 Cube 上：","void OnEnable() { Debug.Log(\"启用\"); }","void OnDisable() { Debug.Log(\"禁用\"); }","void Update() { if (Input.GetKeyDown(KeyCode.H)) { gameObject.SetActive(!gameObject.activeSelf); } }","播放：按 H 键让方块隐藏/显示，观察 Console 输出 OnDisable/OnEnable。","【事件订阅实践】在 OnEnable 里写 health.OnDeath += HandleDeath; 在 OnDisable 里写 health.OnDeath -= HandleDeath;","这样对象被禁用/销毁时自动退订，不会报“已销毁对象仍被调用”错误。","【用途】敌人死亡时先播放特效再销毁、UI 面板开关等。"],
   "tips":[{"t":"success","c":"显隐控制 SetActive 比 Destroy 更省（可复用），配合 OnEnable/OnDisable 完成“复活”逻辑。"}]},
 ],
 "errors":[{"err":"对象禁用后事件仍被调用报错？","why":"没在 OnDisable 退订","fix":"把订阅放 OnEnable、退订放 OnDisable，或退订时判空。"}],
 "exercise":["用 SetActive 控制一个对象显隐并观察生命周期","在 OnEnable/OnDisable 里订阅/退订一个事件","说出 OnEnable 与 Start 的先后关系"],
 "summary":"OnEnable/OnDisable 已掌握。下一课学运行时调试技巧。"},

{"num":89,"title":"运行时调试技巧","summary":"掌握编辑器运行时调试：断点、Inspector 观察、暂停逐帧、调试工具。","keywords":"调试,断点,debugger,暂停,逐帧,运行时查看","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握断点调试","掌握 Inspector 运行时观察","掌握暂停与逐帧排查"],
 "intro":"代码报错或逻辑不对时，除了 Debug.Log，还有更专业的调试手段。本课教你“用编辑器抓 bug”。",
 "sections":[
  {"h":"断点调试（Visual Studio）","lead":"让程序“停在你指定的行”。",
   "steps":["在 Visual Studio 打开脚本，在要检查的代码行左侧灰色区域【点击】打一个红色圆点（断点）。","点编辑器播放，再点 VS 顶部的【附加到 Unity Attach to Unity】（或直接按 F5）。","程序运行到断点处会【暂停】，VS 高亮当前行。","此时可【悬停变量】查看其当前值；用【即时窗口】输入表达式查看。","按【F10】逐语句执行、【F11】进入方法、【Shift+F11】跳出。","查看【监视窗口】添加要跟踪的变量。","排查完毕【移除断点】（点红点），点【继续 Continue】（F5）恢复运行。","【注意】断点会大幅降低运行速度，排查完务必移除。"],
   "tips":[{"t":"note","c":"断点调试能看到“这一刻到底发生了什么”，比 Log 更精确。"}]},
  {"h":"Unity 内置调试技巧","lead":"不开 IDE 也能查。",
   "steps":["【Inspector 实时观察】播放中选中对象，Inspector 里的字段实时变化，直接看到数值怎么变。","【折叠面板折叠调试】播放中可修改 Inspector 数值（停止会还原），用于“试参数”。","【暂停 + 逐帧】播放中点【⏸ 暂停】，再用【Step】逐帧前进，看对象每一帧的位置/状态。","【Game 视图 Stats】Game 视图右上角下拉选【Stats】，显示帧率、Draw Call、三角形数（性能相关）。","【场景视图运行中编辑】运行时在场景里拖动对象，观察实时效果（停止还原）。","【Console 过滤与折叠】用 Collapse、按级别过滤错误。","【Profiler】Window→Analysis→Profiler 看性能瓶颈（第 262 课）。","【Log 定位】Console 双击日志跳到代码行。"],
   "tips":[{"t":"success","c":"调试套路：先看 Console 有没有红叉 → 断点看值 → Inspector 看状态 → 逐帧看过程。"}]},
 ],
 "errors":[{"err":"断点不生效？","why":"VS 未附加到 Unity 或编译后没刷新","fix":"确认 VS 点过“附加到 Unity”；脚本改动后 Unity 重编译需重新附加。"}],
 "exercise":["在某行打断点，附加 Unity 后运行并观察变量","播放中用 Inspector 观察一个字段实时变化","用暂停+逐帧看一个运动物体的位置变化"],
 "summary":"调试技巧已掌握。下一课综合练习：做一个会动的方块。"},

{"num":90,"title":"综合练习：让方块动起来","summary":"综合运用生命周期、Transform、输入、实例化、销毁，做一个完整交互小场景。","keywords":"综合练习,会动的方块,移动,旋转,跳跃,实战","time":"约 25 分钟","difficulty":"入门",
 "objectives":["综合运用本章知识","独立完成交互式小场景","体验完整开发流程"],
 "intro":"把第 6 章的知识全部串起来：做一个小方块，能用键盘移动、旋转、跳跃、发射小球。这是里程碑练习！",
 "sections":[
  {"h":"准备工作","lead":"搭好练习环境。",
   "steps":["新建场景并命名 Practice06。","创建地面：Plane 或 Cube 缩放拉大当地面。","创建主玩家：Cube 命名为 Player，Scale (1,1,1)，位置 (0,1,0)。","给 Player 加 Rigidbody（第 91 课刚体，先加上为跳跃做准备）。","创建子弹预制体：Sphere 缩小、加黄色材质、加 Rigidbody、做成预制体后删除场景中的原型。","创建脚本 PlayerController 挂到 Player 上。","开始写代码（逐步来）。"],
   "tips":[{"t":"note","c":"先搭环境再写代码，避免边写边缺对象。"}]},
  {"h":"编写 PlayerController","lead":"一个脚本搞定移动+跳跃+发射。",
   "steps":["在 PlayerController 里写（用本章学的所有知识）：","public GameObject bulletPrefab; public float speed = 6f; public float jumpPower = 8f; public float rotateSpeed = 120f;","void Update() {","float h = Input.GetAxis(\"Horizontal\"); // 左右","float v = Input.GetAxis(\"Vertical\");   // 前后","transform.Translate(new Vector3(h, 0, v) * speed * Time.deltaTime); // 移动","if (Input.GetKeyDown(KeyCode.Space)) { GetComponent<Rigidbody>().AddForce(Vector3.up * jumpPower, ForceMode.Impulse); } // 跳跃","if (Input.GetKeyDown(KeyCode.Q)) { Instantiate(bulletPrefab, transform.position + transform.forward, transform.rotation); } // 发射","}","【说明】GetAxis 在第 111 课详讲；AddForce 第 94 课；Instantiate 第 76 课。","保存，把子弹预制体拖到 PlayerController 的 bulletPrefab 槽。","播放：WASD 移动、空格跳跃、Q 发射子弹！"],
   "tips":[{"t":"success","c":"你已经能做出“可操作的小游戏片段”了，后续课程就是把这些能力打磨得更专业。"}]},
  {"h":"收尾与优化","lead":"验证与整理。",
   "steps":["给子弹加自动销毁：在子弹预制体加脚本，3 秒后 Destroy（第 77 课）。","让子弹朝前方飞：子弹脚本里 transform.Translate(Vector3.forward * 10f * Time.deltaTime)。","检查 Console 无报错、无警告。","保存场景与项目。","试着调整 speed/jumpPower 数值体验不同手感。","把 PlayerController 的字段用 Header/Range 整理好（第 84 课）。","总结：本场景用到了生命周期、Transform、输入、刚体、实例化、销毁、预制体。"],
   "tips":[{"t":"note","c":"完成一个“小闭环”后保存、整理、复盘，学习效果最好。"}]},
 ],
 "errors":[{"err":"空格跳跃没反应？","why":"Rigidbody 缺失或跳跃力太小","fix":"确认 Player 有 Rigidbody；jumpPower 调到 8 以上；检查 AddForce 是否被重力抵消。"}],
 "exercise":["完成移动+跳跃+发射的 PlayerController","给子弹加方向与自动销毁","调整参数找到合适手感"],
 "summary":"综合练习完成！你已拥有“会动的方块”。下一章进入物理系统，让世界更真实。"},

# ============ 第7章 物理系统 (91-110) ============
{"num":91,"title":"刚体 Rigidbody 详解","summary":"掌握刚体：让物体受重力、受力、碰撞，理解刚体的核心属性。","keywords":"rigidbody,刚体,重力,质量,约束,物理","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解刚体的作用","掌握刚体核心属性","学会添加与配置刚体"],
 "intro":"想让物体“像现实中一样下落、碰撞、受力”，给它加刚体（Rigidbody）。它是物理世界的“身份证”。",
 "sections":[
  {"h":"什么是刚体","lead":"物理世界的主宰。",
   "steps":["刚体（Rigidbody）让对象参与 Unity 物理模拟：受重力、受力、与其他碰撞体交互。","【添加】选中对象 → Inspector → Add Component → 搜索 Rigidbody → 添加。","添加后播放，物体会受重力下落（若无地面会一直掉）。","【核心属性】","Mass 质量：越大越“重”，影响受力后的加速度。","Drag 线性阻尼：越大速度衰减越快（空气阻力感）。","Angular Drag 角阻尼：旋转衰减。","Use Gravity 使用重力：勾选则受重力。","Is Kinematic 运动学：勾选后不受力/重力控制，只能由代码/动画移动，但仍参与碰撞（适合移动平台、被动画驱动的角色）。","Interpolate 插值：消除抖动（第 109 课）。","Constraints 约束：冻结某些轴的移动/旋转（第 97 课）。"],
   "tips":[{"t":"note","c":"刚体 + 碰撞体 = 完整物理参与。只有刚体没有碰撞体，物体会“穿墙”。"}]},
  {"h":"刚体的移动方式","lead":"分清“推”与“搬”。",
   "steps":["【方式1 施加力】rb.AddForce(Vector3.up * 10f)：物理真实，受质量影响。","【方式2 改速度】rb.velocity = new Vector3(x, rb.velocity.y, z)：直接控制速度（适合角色移动）。","【方式3 瞬移】rb.MovePosition(target)：平滑移动，常用于移动平台/受控对象。","【方式4 直接改 Transform】rb.transform.position = ...：绕过物理（碰撞会不准确，慎用）。","【推荐】角色移动常用 velocity 或 AddForce；动态物体多用 AddForce；平台/电梯用 MovePosition 或 Kinematic。","【重要】物理操作放 FixedUpdate 里（第 72 课）。","【获取速度】rb.velocity 用于检测移动状态。"],
   "tips":[{"t":"danger","c":"不要每帧直接改带刚体对象的 transform.position（会与物理冲突导致穿透/抖动）；用 velocity 或 MovePosition。"}]},
 ],
 "errors":[{"err":"物体加了刚体却不动？","why":"Use Gravity 未勾选，或质量太大/力太小","fix":"检查 Use Gravity；调大力或减小质量。"}],
 "exercise":["给两个物体加不同 Mass，从高处下落对比","体验 Is Kinematic 对下落的影响","用 velocity 实现一个水平移动的刚体方块"],
 "summary":"刚体已掌握。下一课学碰撞体 Collider。"},

{"num":92,"title":"碰撞体 Collider 类型","summary":"掌握 Box/Sphere/Capsule/Mesh 碰撞体的选择、配置与复合碰撞体。","keywords":"collider,碰撞体,box collider,sphere,mesh collider,碰撞","time":"约 15 分钟","difficulty":"入门",
 "objectives":["认识常见碰撞体类型","掌握碰撞体配置","会用复合碰撞体"],
 "intro":"碰撞体决定“物体哪里可以被撞、撞到的范围是什么形状”。选对碰撞体，物理才准确又高效。",
 "sections":[
  {"h":"常见碰撞体类型","lead":"按形状选。",
   "steps":["【Box Collider 盒体】：长方体碰撞，适合盒子、墙、箱子，性能好、最常用。","【Sphere Collider 球体】：球形碰撞，适合球、圆角物体。","【Capsule Collider 胶囊】：圆柱+半球，适合角色（人形、柱子）。","【Mesh Collider 网格】：用模型的实际网格做碰撞，最精确但最耗性能（静态环境可用）。","【其他】Terrain Collider（地形）、2D 系列（第 204 课）。","【添加】Add Component → 搜 Collider；Unity 给基本几何体自动加对应碰撞体。","【Is Trigger 触发器】：勾选后不再“阻挡”，而是触发事件（第 96 课）。","【Center/Size】：调整碰撞体的位置与大小。","【注意】带刚体的物体必须有碰撞体才能被撞；静态物体（无刚体）有碰撞体即可阻挡。"],
   "tips":[{"t":"note","c":"性能优先级：Box/Sphere/Capsule 简单碰撞 >> Mesh 精确碰撞。能用简单的绝不用网格。"}]},
  {"h":"碰撞体与刚体的配合","lead":"正确组合。",
   "steps":["【静态障碍】无刚体 + 有碰撞体：不可移动，能阻挡其他物体（墙、地面）。","【动态物体】有刚体 + 有碰撞体：受重力、可被推（箱子、球）。","【触发区域】有刚体（或脚本） + Is Trigger 碰撞体：不阻挡，只触发事件（检测进入区域）。","【复合碰撞体】一个对象挂多个碰撞体：如“人形”用多个胶囊/球拼出身体形状（比单个大盒子更贴合）。","【子对象碰撞体】碰撞体也可挂在子对象上，组成复杂结构（每个子碰撞体独立）。","【实战】给一个“茶壶”模型（复杂形状）添加多个 Box Collider 组合出近似碰撞。","【Mesh Collider 优化】静态场景用 Convex 勾选可移动但成本高；一般只用于静态。"],
   "tips":[{"t":"success","c":"碰撞体选择口诀：方盒子用 Box、圆的用 Sphere、人形用 Capsule、复杂静态才用 Mesh。"}]},
 ],
 "errors":[{"err":"物体穿过地面掉下去？","why":"地面无碰撞体，或刚体速度过快","fix":"确认地面有碰撞体；速度过快可开启刚体 Collision Detection 的 Continuous（第 97 课）。"}],
 "exercise":["给三个不同形状物体配置合适碰撞体","用复合碰撞体拼出一个简单人形","对比 Box 与 Mesh 碰撞体的性能差异"],
 "summary":"碰撞体已掌握。下一课学物理材质 Physic Material。"},

{"num":93,"title":"物理材质 Physic Material","summary":"掌握物理材质：调节摩擦与弹性，做出滑冰、弹跳、粗糙等不同表面。","keywords":"physic material,物理材质,摩擦,弹性,bounciness","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解物理材质作用","掌握创建与配置","做出不同材质表面"],
 "intro":"同样一个球，落在冰面滑得远、落在地毯上马上停——这就是摩擦与弹性在起作用，由物理材质控制。",
 "sections":[
  {"h":"创建物理材质","lead":"三步创建。",
   "steps":["在 Project 里右键 →【创建 Create】→【物理材质 Physic Material】（注意别选 2D 的 Physics Material 2D）。","命名如 Ice、Bouncy、Rough。","选中它，Inspector 显示属性。","【Dynamic Friction 动摩擦】：物体滑动时的摩擦力，0=无摩擦（冰），1=高摩擦。","【Static Friction 静摩擦】：物体静止时开始移动需要的力。","【Bounciness 弹性】：0=不弹，1=完全弹（数值可大于 1）。","【Friction Combine / Bounce Combine】摩擦/弹性的合成方式：Average（平均）默认、Minimum、Maximum、Multiply。","把物理材质拖到碰撞体的【Material】槽即可应用。"],
   "tips":[{"t":"note","c":"冰面 = 摩擦 0、弹性 0；弹力球 = 摩擦 0.2、弹性 0.8。"}]},
  {"h":"实战：弹力球与滑冰面","lead":"体验两种材质。",
   "steps":["创建物理材质 Bouncy：Bounciness=0.8，Friction=0。","创建物理材质 Ice：Friction=0，Bounciness=0。","场景里放一个高台（Cube），高台上放一个 Sphere（带刚体）。","把 Bouncy 材质拖到 Sphere 的 Sphere Collider 的 Material 槽。","播放：球落下后高高弹起。","再复制一个球，把 Ice 材质拖给它，放在另一个带 Ice 材质的地面上。","播放：两个球对比——一个弹跳、一个滑行很远。","【注意】物理材质要赋给【碰撞体】的 Material 槽，不是 Mesh Renderer 的材质！","【调整】Bounciness 太高会越弹越高，用 Bounce Combine 的 Maximum 控制。"],
   "tips":[{"t":"warn","c":"物理材质是赋给 Collider 的，千万别和“外观材质 Material”搞混（一个是物理、一个是渲染）。"}]},
 ],
 "errors":[{"err":"球不弹跳？","why":"物理材质没赋到 Collider，或弹性参数太小","fix":"确认材质拖到 Collider 的 Material 槽；Bounciness 设 0.5 以上。"}],
 "exercise":["创建冰面、粗糙面、弹力面三种物理材质","分别测试球在三种表面上的表现","调整摩擦与弹性找到最明显的对比"],
 "summary":"物理材质已掌握。下一课学施加力 AddForce。"},

{"num":94,"title":"给物体施加力 AddForce","summary":"掌握 AddForce 的用法与 ForceMode 四种模式，做出真实受力效果。","keywords":"addforce,施加力,force,forcemode,冲量,推进","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 AddForce 语法","理解 ForceMode 四种模式","用受力实现推进/爆炸"],
 "intro":"AddForce 让刚体“被推一把”。理解四种力的模式，才能做出想要的物理效果。",
 "sections":[
  {"h":"AddForce 基础","lead":"给刚体一个“推力”。",
   "steps":["语法：rb.AddForce(Vector3 方向 * 力度);","例：rb.AddForce(Vector3.up * 500f); 把物体向上推。","【执行位置】物理相关放 FixedUpdate 里（第 72 课）。","【四种模式 ForceMode】","ForceMode.Force（默认）：持续的力，随质量影响，适合推进、持续加速。","ForceMode.Acceleration：持续加速度（忽略质量），适合统一加速。","ForceMode.Impulse：瞬间冲量（一次性猛推），适合跳跃、爆炸、开枪后坐力。","ForceMode.VelocityChange：瞬间速度改变（忽略质量），适合直接设定速度变化。","【选择】一次性“撞飞”用 Impulse；持续“推走”用 Force。","【质量影响】Force 与 Impulse 受质量影响：质量大的物体被同样的力推动得慢。","【方向】可以是世界方向（Vector3.up）或自身方向（transform.forward）。"],
   "tips":[{"t":"note","c":"理解重点：Impulse 像“踢一脚”，Force 像“一直推”，二者手感完全不同。"}]},
  {"h":"实战：跳跃与加农炮","lead":"体验不同模式。",
   "steps":["【跳跃（Impulse）】在 Player 脚本里：if (Input.GetKeyDown(KeyCode.Space)) { GetComponent<Rigidbody>().AddForce(Vector3.up * 8f, ForceMode.Impulse); }","注意：跳跃力要能克服重力，8-10 较合适；落地后还要允许再跳（判断在地面）。","【持续推进（Force）】给火箭做推进：rb.AddForce(transform.up * 50f, ForceMode.Force); 放 FixedUpdate 里，火箭持续上升。","【爆炸（Impulse 方向）】给物体一个随机方向的爆炸力：rb.AddForce(dir * power, ForceMode.Impulse); dir 是“从爆炸点到物体”的方向。","【对比】同一力度分别用 Force 与 Impulse，观察物体被“持续推”与“瞬间撞飞”的差异。","【注意】力的方向尽量单位化再乘力度，避免斜向力过大。"],
   "tips":[{"t":"success","c":"跳跃 = Impulse 一次性冲量；火箭 = Force 持续推力。牢记两种模式的差别。"}]},
 ],
 "errors":[{"err":"物体没被推动？","why":"力太小或对象无刚体","fix":"确认有 Rigidbody；把力调大；确认在 FixedUpdate 里调用。"}],
 "exercise":["用 Impulse 做一个能跳的方块","用 Force 做一个持续上升的火箭（可乘 Time.fixedDeltaTime）","对比四种 ForceMode 的效果差异"],
 "summary":"AddForce 已掌握。下一课学扭矩与角速度。"},

{"num":95,"title":"扭矩与角速度 Torque","summary":"掌握 AddTorque 让刚体旋转、控制角速度，做旋转类的物理效果。","keywords":"torque,扭矩,addtorque,角速度,旋转力","time":"约 12 分钟","difficulty":"入门",
 "objectives":["理解扭矩概念","掌握 AddTorque 用法","掌握角速度控制"],
 "intro":"AddForce 让物体“移动”，AddTorque 让物体“转动”。本课学习旋转类物理。",
 "sections":[
  {"h":"扭矩基础","lead":"“旋转的力”。",
   "steps":["扭矩（Torque）= 让刚体绕轴旋转的“转动力”。","语法：rb.AddTorque(Vector3 轴 * 力度);","例：rb.AddTorque(Vector3.up * 10f); 让物体绕 Y 轴旋转。","【旋转轴】绕哪个轴转就用哪个轴的向量：Vector3.right（绕 X）、Vector3.up（绕 Y）、Vector3.forward（绕 Z）。","【Angular Velocity 角速度】物体当前的旋转速度：rb.angularVelocity 可读可设。","【直接设角速度】rb.angularVelocity = Vector3.up * 3f; 让物体以固定速度自转。","【Angular Drag 角阻尼】让旋转逐渐停止的参数（刚体属性）。","【ForceMode 同样适用】AddTorque 也有 ForceMode（Impulse 可瞬间给旋转冲量）。"],
   "tips":[{"t":"note","c":"需要“一直转”用角速度（angularVelocity），需要“被推转”用 AddTorque。"}]},
  {"h":"实战：旋转陀螺与翻滚","lead":"两个小练习。",
   "steps":["【自转陀螺】给圆柱（带刚体）写：void FixedUpdate() { rb.AddTorque(Vector3.up * 5f); } 播放：圆柱持续旋转。","【翻滚方块】给方块 AddTorque(Vector3.right * 30f, ForceMode.Impulse) 一次性翻出去。","【角速度设定】rb.angularVelocity = Vector3.up * 2f; 物体匀速自转，不受重力倾斜影响（配合 Is Kinematic 更稳）。","【让旋转减速】把 Angular Drag 调大，旋转逐渐停止。","【检测是否在旋转】rb.angularVelocity.magnitude > 0.1f 判断。","【应用】齿轮转动、陀螺、翻滚的箱子、转动的风扇（风扇更推荐第 81 课 Rotate 或动画）。","【注意】纯视觉旋转（不参与物理）用 transform.Rotate 更省；物理旋转才用 Torque。"],
   "tips":[{"t":"warn","c":"刚体旋转与 transform.Rotate 混用会互相干扰，二选一：物理对象用 Torque/angularVelocity，普通对象用 Rotate。"}]},
 ],
 "errors":[{"err":"物体不转？","why":"无刚体、扭矩太小或角阻尼过大","fix":"确认有 Rigidbody；调大扭矩；把 Angular Drag 调小。"}],
 "exercise":["让一个圆柱持续绕 Y 轴旋转","用 Impulse 扭矩让方块翻滚","用 angularVelocity 设定固定旋转速度"],
 "summary":"扭矩与角速度已掌握。下一课学触发器 Trigger 与碰撞事件。"},

{"num":96,"title":"触发器 Trigger 与碰撞事件","summary":"掌握 OnTrigger 与 OnCollision 事件，实现进入区域、碰触伤害等逻辑。","keywords":"trigger,触发器,oncollision,ontrigger,碰撞事件,进入区域","time":"约 16 分钟","difficulty":"入门",
 "objectives":["理解触发与碰撞的区别","掌握两个事件系列","实现进入区域检测"],
 "intro":"“玩家踩到金币”“敌人碰到玩家扣血”“走进区域触发剧情”——全靠触发与碰撞事件。这是游戏交互的核心。",
 "sections":[
  {"h":"碰撞与触发的区别","lead":"“挡”与“穿”。",
   "steps":["【碰撞 Collision】碰撞体未勾 Is Trigger：物理阻挡，物体撞上会停下/反弹。回调方法：OnCollisionEnter / Stay / Exit。","【触发 Trigger】碰撞体勾选 Is Trigger：不阻挡、穿透，只“报告”进入了区域。回调方法：OnTriggerEnter / Stay / Exit。","【触发要求】触发双方至少一方带刚体（通常动态物体带刚体，触发区不带）。","【事件参数】OnTriggerEnter(Collider other)：other 是“进入者”的碰撞体；通过 other.gameObject 拿对象、other.tag 判断身份。","【碰撞事件】OnCollisionEnter(Collision collision)：collision 有 contact 点、相对速度等详细信息。","【命名】OnCollisionEnter/Stay/Exit 与 OnTriggerEnter/Stay/Exit，别写错（Collision vs Trigger）。"],
   "tips":[{"t":"note","c":"判断“是否碰到了”用碰撞；判断“是否进入了区域/道具范围”用触发。"}]},
  {"h":"实战：金币收集与陷阱","lead":"用触发实现金币与伤害。",
   "steps":["【金币】创建 Sphere 命名为 Coin，缩小、加金色材质，勾选 Sphere Collider 的 Is Trigger，旋转让金字样自然。","给 Coin 加脚本：","void OnTriggerEnter(Collider other) { if (other.CompareTag(\"Player\")) { Debug.Log(\"金币+1\"); Destroy(gameObject); } }","给玩家 Cube 加 Tag “Player”（第 78 课）。","播放：控制玩家靠近金币，进入区域即触发，金币消失！","【陷阱区域】创建一个 Cube 拉大压扁，勾选 Is Trigger，挂脚本：OnTriggerEnter 时 other 是玩家则扣血。","【持续伤害】用 OnTriggerStay（每帧都触发）实现“站在火里持续掉血”，注意用时间间隔控制。","【离开区域】OnTriggerExit 实现“离开安全区”。","【碰撞销毁】子弹用 OnCollisionEnter 撞到墙就 Destroy（第 77 课）。"],
   "tips":[{"t":"success","c":"触发事件三件套：Enter 进入、Stay 停留、Exit 离开；配合 Tag 判断对象身份。"}]},
 ],
 "errors":[{"err":"OnTriggerEnter 没触发？","why":"双方都没刚体，或触发器没勾 Is Trigger","fix":"确认动态对象有 Rigidbody；触发器勾选 Is Trigger；检查方法名拼写。"}],
 "exercise":["做一个金币收集系统（触发）","做一个持续伤害的陷阱区域（OnTriggerStay）","用 OnCollisionEnter 让子弹撞墙销毁"],
 "summary":"触发与碰撞事件已掌握。下一课学刚体的 Sleep 与约束。"},

{"num":97,"title":"刚体约束与 Sleep、碰撞检测模式","summary":"掌握刚体约束（冻结轴）、Sleep 休眠、Collision Detection 模式，完善物理细节。","keywords":"刚体约束,冻结,sleep,休眠,collision detection,continuous","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握刚体约束冻结","理解 Sleep 机制","掌握碰撞检测模式"],
 "intro":"“让车轮只滚不滑”“防止高速穿透”……本课解决物理进阶细节。",
 "sections":[
  {"h":"刚体 Constraints 约束","lead":"冻结某些轴的移动/旋转。",
   "steps":["在刚体组件的【Constraints】区域，有 Freeze Position（冻结位置）与 Freeze Rotation（冻结旋转）。","每个轴可单独勾选：Freeze Position Y 勾选 = 物体不会沿 Y 轴移动（可用于锁定高度）。","Freeze Rotation X/Z 勾选 = 物体不会向侧倾倒（做“不倒的角色”常用）。","【应用】角色/车辆防止翻倒：冻结 Rotation X 和 Z。","【应用】只让物体水平移动：冻结 Position Y。","【应用】飞机不翻滚：冻结部分旋转轴。","【注意】约束对刚体“物理运动”生效；transform 直接改位置仍可动。"],
   "tips":[{"t":"note","c":"角色控制器常用：冻结旋转 X/Z，避免人物被撞倒乱滚。"}]},
  {"h":"Sleep 休眠与碰撞检测","lead":"性能与防穿透。",
   "steps":["【Sleep 休眠】刚体静止一段时间后进入“睡眠”，停止物理计算，省性能。","【唤醒】受到碰撞/力时自动唤醒。","【判断休眠】rb.IsSleeping() 返回 bool；rb.Sleep()/rb.WakeUp() 手动控制。","【Sleep Threshold】刚体属性：休眠阈值（速度低于此值即入睡），调小更不易睡（默认 0.005）。","【Collision Detection 碰撞检测模式】","Discrete（离散，默认）：速度太快可能穿透薄墙。","Continuous：持续检测，防止高速穿透（对快速子弹/角色推荐，成本略高）。","Continuous Dynamic：与 Continuous 配合的动态对象。","Continuous Speculative：折中方案。","【应用】高速子弹、快速移动角色设 Continuous，避免“穿墙”。"],
   "tips":[{"t":"warn","c":"高速物体穿透是经典 bug，设置 Collision Detection=Continuous 能解决，但别全开（性能）。"}]},
 ],
 "errors":[{"err":"角色撞一下就被撞飞乱滚？","why":"旋转未冻结","fix":"在刚体 Constraints 里勾选 Freeze Rotation X 与 Z。"}],
 "exercise":["做一个只水平移动不倾倒的方块","体验刚体休眠与唤醒","给高速子弹设 Continuous 防穿透"],
 "summary":"约束与检测模式已掌握。下一课学关节 Joint。"},

{"num":98,"title":"关节 Joint 详解","summary":"掌握铰链/弹簧/固定关节，做出门、摆锤、绳索、悬挂等联动物体。","keywords":"joint,关节,hijoint,springjoint,fixedjoint,铰链,摆锤","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解关节的作用","掌握常用关节类型","做出摆锤与门"],
 "intro":"“门能绕轴转”“钟摆来回晃”“两个物体被弹簧连着”——关节（Joint）把物体“连”起来，产生联动。",
 "sections":[
  {"h":"关节基础与类型","lead":"认识常见关节。",
   "steps":["关节（Joint）连接两个刚体（或一个刚体与世界），产生约束力。","【Hinge Joint 铰链】：绕一个轴旋转，像门、摆锤、车轮轴。","【Spring Joint 弹簧】：像弹簧一样连接两点，有弹性伸缩。","【Fixed Joint 固定】：把两个物体固定在一起，像一个整体。","【Character Joint 角色关节】/Configurable Joint：进阶（布娃娃用）。","【添加】给物体加 Rigidbody → Add Component → 选关节类型。","【连接对象】关节的 Connected Body 槽拖入另一个刚体（空则连接世界/固定点）。","【共同要求】被连接的物体必须带刚体。"],
   "tips":[{"t":"note","c":"关节是物理约束：它不让物体“自由飞翔”，而是“按规则相连”。"}]},
  {"h":"实战：摆锤与门","lead":"两个经典应用。",
   "steps":["【摆锤】创建“支架”（静止 Cube 无刚体或有刚体冻结），下面挂一个球：","给球加 Rigidbody，再给它加 Hinge Joint。","在 Hinge Joint 的【Anchor】设 (0, 0.5, 0)（球上方连接点），【Connected Body】留空（连接世界）。","播放：球像钟摆一样来回摆动！","【门】做一个“门板” Cube + 刚体 + Hinge Joint，Anchor 设在门的一侧边缘，让门绕铰链转动。","【弹簧】创建弹簧关节：连接两个球，调整 Spring/Damper 数值，播放看弹性伸缩。","【固定】Fixed Joint 把两个物体焊在一起移动。","【参数】Hinge Joint 的 Limits（角度限制）可让门只开 90 度。","【注意】关节调参需要耐心，先小步调整数值观察。"],
   "tips":[{"t":"success","c":"摆锤（Hinge）与固定（Fixed）最常用，掌握这两个就够应付多数物理结构。"}]},
 ],
 "errors":[{"err":"关节连接后乱飞？","why":"Anchor/连接点设置不当或物体初始位置不合理","fix":"先把连接物体摆好相对位置，再设 Anchor；必要时冻结部分轴。"}],
 "exercise":["做一个会摆动的钟摆","做一个只能开 90 度的门","用 Fixed Joint 把两个物体固定在一起"],
 "summary":"关节已掌握。下一课学物理层碰撞矩阵。"},

{"num":99,"title":"物理层 Layer 碰撞矩阵","summary":"掌握碰撞矩阵：控制哪些层之间发生碰撞，优化物理并实现“选择性碰撞”。","keywords":"碰撞矩阵,layer collision matrix,物理层,过滤碰撞,layermask","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解碰撞矩阵原理","掌握配置碰撞规则","掌握代码 LayerMask 过滤"],
 "intro":"“子弹不打队友”“玩家不撞玩家”——通过物理层 + 碰撞矩阵控制“谁和谁碰撞”，让物理按规则运行。",
 "sections":[
  {"h":"碰撞矩阵配置","lead":"在设置里划规则。",
   "steps":["先创建物理层：Edit → Project Settings → Tags and Layers → 在 User Layer 输入层名（如 Player、Enemy、Bullet、Wall）。","给对象设置 Layer（Inspector 顶部的 Layer 下拉，第 78 课）。","打开碰撞矩阵：Edit → Project Settings → Physics（或 Physics 2D）→ Layer Collision Matrix。","矩阵是一个“网格”，行与列的交叉勾选 = 这两个层会发生碰撞。","【配置示例】让 Bullet 只与 Wall 和 Enemy 碰撞、不与 Player 碰撞：取消 Bullet 行与 Player 列的勾选。","【效果】勾掉的组合不再发生物理碰撞与触发。","【注意】碰撞矩阵是全局配置，影响所有对象。"],
   "tips":[{"t":"note","c":"正确分层 + 矩阵，能大幅减少不必要的碰撞计算，是性能优化手段之一（第 16 章）。"}]},
  {"h":"代码中用 LayerMask","lead":"在射线/物理查询里过滤。",
   "steps":["【LayerMask 字段】public LayerMask targetMask; 在 Inspector 勾选要检测的层。","【射线过滤】Raycast 的 LayerMask 参数只检测指定层（第 100 课详讲）：","int layer = LayerMask.NameToLayer(\"Enemy\");","int mask = 1 << layer; // 位运算生成掩码","Physics.Raycast(ray, out hit, 100f, mask);","【物理查询】OverlapSphere、SphereCast 等都有 LayerMask 参数（第 102 课）。","【检测某层】Physics.Raycast(..., 1 << LayerMask.NameToLayer(\"Enemy\"))。","【实战】子弹射线只检测敌人层，忽略其他，实现“只打敌人”。","【注意】LayerMask 用位运算组合：mask = (1 << layerA) | (1 << layerB)。"],
   "tips":[{"t":"note","c":"位运算 1 << layer 生成掩码要记住：它是 Unity 物理查询的标配。"}]},
 ],
 "errors":[{"err":"物体明明有碰撞体却互相穿过？","why":"两个层的碰撞矩阵被取消了","fix":"检查 Physics 的 Layer Collision Matrix，把对应行列勾上。"}],
 "exercise":["创建 Player/Enemy/Bullet/Wall 四层","配置矩阵：子弹只碰墙和敌人","用 LayerMask 让射线只检测敌人层"],
 "summary":"物理层与碰撞矩阵已掌握。下一课学射线检测 Raycast。"},

{"num":100,"title":"射线检测 Raycast 入门","summary":"掌握 Raycast：从一点发射射线检测碰撞，用于点击、射击、探测前方。","keywords":"raycast,射线,射线检测,ray,hit,raycasthit","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解射线的概念","掌握 Raycast 语法","实现点击拾取与前方探测"],
 "intro":"“鼠标点中了哪个物体？”“前方 3 米有没有墙？”——射线（Ray）是 Unity 里“用线检测”的利器，应用极广。",
 "sections":[
  {"h":"射线基础","lead":"“一根看不见的激光笔”。",
   "steps":["射线 = 从某个点向某个方向发射的“无限长/有限长的线”，检测它穿过了什么。","语法：Physics.Raycast(起点, 方向, out 命中信息, 最大距离);","【返回】bool：是否命中。true=有物体被射中。","【命中信息 out hit】RaycastHit hit：包含命中的碰撞体、点、法线、距离。","【方向】用单位向量（normalized）表示方向。","【最简写法】","if (Physics.Raycast(transform.position, transform.forward, out RaycastHit hit, 10f)) { Debug.Log(\"射中：\" + hit.collider.name); }","【LayerMask 过滤】加第 5 参数：Physics.Raycast(..., mask) 只检测指定层。","【可视调试】Debug.DrawRay(起点, 方向 * 距离, Color.red); 在场景里画出射线。","【适用】射击命中检测、点击物体、前方障碍检测、视线检测。"],
   "tips":[{"t":"note","c":"Debug.DrawRay 是调试射线的必备，先画出来再调逻辑，事半功倍。"}]},
  {"h":"实战：点击拾取物体","lead":"鼠标点中哪个就打印哪个。",
   "steps":["新建脚本 RayDemo 挂到 Camera（或空对象）上。","在 Update 里写：","if (Input.GetMouseButtonDown(0)) {","Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition); // 屏幕点转射线","if (Physics.Raycast(ray, out RaycastHit hit, 100f)) { Debug.Log(\"点击了：\" + hit.collider.name); }","}","【解释】ScreenPointToRay 把鼠标屏幕坐标转成从相机发出的世界射线。","播放：用鼠标点击场景里的各个物体，Console 输出被点中的名字。","【进阶】根据名字/标签做不同响应：点击敌人扣血、点击金币收集。","【前方探测】transform.forward 方向 Raycast，检测前方是否有墙/敌人（AI 用）。","【注意】被点物体需要有碰撞体，射线才能命中。"],
   "tips":[{"t":"success","c":"“屏幕坐标 → 射线 → 命中对象”是“点击游戏”的标准套路，务必熟练。"}]},
 ],
 "errors":[{"err":"点击没有反应？","why":"物体无碰撞体、或射线方向错误、或 Camera.main 为 null","fix":"确认物体有碰撞体；确认用了 ScreenPointToRay；确认相机 Tag 是 MainCamera。"}],
 "exercise":["实现鼠标点击打印物体名","用 forward 射线检测前方 5 米是否有障碍","用 Debug.DrawRay 可视化射线"],
 "summary":"Raycast 已入门。下一课进阶：射线过滤、命中信息与物理查询。"},
]
